/** Box scene drawn with these pens in any parallel view, for the Chapter 02 drawings.
 * P(x, y, z) returns a screen point with depth; toward is the unit vector to the viewer in the
 * same coordinates, and s the unit vector to the sun. */
export function penScene(k, P, toward, boxes, s, opts = {}) {
  const p = pens(k, 11), Q = r => P(r.x, r.y, r.z ?? 0);
  return scene(p, Q, boxes, s, fc => fc.side * toward[AX.indexOf(fc.axis)] > 1e-6, r => Q(r).depth, opts);
}

/** Two-point perspective camera with a horizontal line of sight (azimuth yaw, focal length fl). */
function camera(eye, yaw, fl, cx, cy) {
  const F = pt(sind(yaw), cosd(yaw)), R = pt(cosd(yaw), -sind(yaw));
  const P = q => { const d = sub(q, eye), z = dot(d, F); return { x: cx + fl * dot(d, R) / z, y: cy - fl * d.z / z }; };
  P.vp = v => { const z = dot(v, F); return Math.abs(z) < 1e-9 ? null : { x: cx + fl * dot(v, R) / z, y: cy - fl * (v.z ?? 0) / z }; };
  P.facing = fc => fc.side * (eye[fc.axis] - fc.value) > 1e-6;
  P.nearness = q => -Math.hypot(q.x - eye.x, q.y - eye.y);
  P.horizon = cy;
  return P;
}

/* ── Figures ──────────────────────────────────────────────────────────────── */

/** Thin members (poles, rods) are single heavy strokes; their shadows are narrow hatched strips. */
const member = (p, P, a, b) => p.line(P(a), P(b), { w: 2.6, over: 0 });
function strip(p, P, a, b) {
  const A = P(a), B = P(b), L = Math.hypot(B.x - A.x, B.y - A.y) || 1, n = { x: -(B.y - A.y) / L * 2.6, y: (B.x - A.x) / L * 2.6 };
  const q = [{ x: A.x + n.x, y: A.y + n.y }, { x: B.x + n.x, y: B.y + n.y }, { x: B.x - n.x, y: B.y - n.y }, { x: A.x - n.x, y: A.y - n.y }];
  return p.hatch([q], { gap: 1.8, jitter: .2 }) + p.poly(q, { w: PEN.hatch, over: 0 });
}

const swatch = (p, x, y, w, h, kind) => {
  const r = [{ x, y }, { x: x + w, y }, { x: x + w, y: y + h }, { x, y: y + h }];
  const fill = { light: '', shade: p.hatch([r], { gap: 7.5 }), shadow: p.hatch([r], { gap: 3.4 }),
    cross: p.hatch([r], { gap: 4.2 }) + p.hatch([r], { gap: 4.2, angle: 135 }), stipple: p.stipple([r], 3.6),
    dark: p.hatch([r], { gap: 2.2 }) + p.hatch([r], { gap: 2.6, angle: 135 }) }[kind];
  return fill + p.poly(r, { w: PEN.edge, over: 2 });
};

/* 1 · Light, shade, shadow */
export function figSketchVocabulary(standalone = false) {
  const k = kit(standalone, 'skv'), p = pens(k, 3), c = k.c, s = sunVector(36, 128);
  const main = box(0, 6, 0, 4, 0, 4.5), canopy = box(.8, 4.4, -1.7, 0, 3, 3.2);
  const { P, back, front } = axoScene(p, [main, canopy], s, { psi: 212, eps: 27, frame: { x: 215, y: 60, w: 560, h: 300 } });
  let body = k.group('shadows-ground', back) + k.group('building', front);
  // One corner worked through: the ray through the top meets the ground on the bearing line.
  const top = pt(0, 0, 4.5), base = pt(0, 0), tip = groundPoint(top, s), sky = add(top, mul(s, 1.4));
  body += k.group('construction', p.line(P(sky), P(tip), { w: 1.1, color: c.alt, arrow: 'alt', bow: 0 }) + p.dot(P(tip), 2.6, c.alt)
    + k.label(P(sky).x + 6, P(sky).y - 4, 'sun ray', { size: 11.5, fill: c.alt, weight: 650 }));
  const wallShadow = clipRect(castOnPlane(canopy, s, 'y', 0, -1), [0, 6, 0, 4.5]);
  const onWall = lift('y', 0, { x: wallShadow.reduce((m, q) => m + q.x, 0) / wallShadow.length, y: wallShadow.reduce((m, q) => m + q.y, 0) / wallShadow.length });
  const roof = pt(3.4, 2.6, 4.5), west = pt(0, 2.4, 3), ground = lerp(groundPoint(pt(0, 4, 4.5), s), pt(0, 2), .45), edge = pt(0, 0, 1.2), line = lerp(P(base), P(tip), .62);
  body += k.group('labels', [
    p.callout(20, 110, 'SHADE', ['surface turned away', 'from the sun'], P(west), 'left'),
    p.callout(20, 250, 'SHADOW', ['light blocked by', 'another object'], P(ground), 'left'),
    p.callout(20, 390, 'SHADOW LINE', ['shadow of the casting edge,', 'along the bearing AZI + 180°'], line, 'left'),
    p.callout(800, 90, 'LIGHT', ['faces the sun:', 'leave it white'], P(roof)),
    p.callout(800, 300, 'SHADOW ON A WALL', ['cast by the canopy', 'onto a lit surface'], P(onWall)),
    p.callout(800, 400, 'CASTING EDGE', ['line between light', 'and shade'], P(edge)),
  ].join(''));
  const sw = [['light', 'Light'], ['shade', 'Shade'], ['shadow', 'Shadow']];
  body += k.group('value-key', sw.map(([kind, name], i) => swatch(p, 220 + i * 92, 470, 44, 30, kind) + k.text(272 + i * 92, 490, name, { size: 11.5, fill: c.ink })).join('')
    + k.text(510, 490, 'Value order: shadow darkest, shade lighter, light surfaces white.', { size: 11.5 }));
  return svgDocument(k, { width: 1000, height: 520, title: 'Light, shade and shadow on a box with a canopy', body });
}

/* 2 · Four rules for casting shadows */
export function figSketchRules(standalone = false) {
  const k = kit(standalone, 'skr'), p = pens(k, 5), c = k.c, s = sunVector(42, 145), W = 250;
  const frame = (i, pts) => fitAxo(205, 30, pts, { x: 24 + i * W, y: 78, w: W - 48, h: 190 });
  const rectPts = (x0, x1, y0, y1) => [pt(x0, y0), pt(x1, y0), pt(x1, y1), pt(x0, y1)];
  const plate = (P, x0, x1, y0, y1) => p.poly(rectPts(x0, x1, y0, y1).map(P), { w: PEN.pencil, color: c.axis, over: 4 });
  const ray = (P, from, to) => p.line(P(add(from, mul(s, 1.5))), P(to), { w: .9, color: c.alt, arrow: 'alt', bow: 0 }) + p.dot(P(to), 2.2, c.alt);
  const rod = (P, a, b) => member(p, P, a, b), shadow = (P, a, b) => strip(p, P, a, b);
  const onWall = (q, y) => sub(q, mul(s, (q.y - y) / s.y));
  const panels = [];
  // 1: vertical edges on the ground
  {
    const poles = [[pt(0, 0), 3.2], [pt(2.4, -1.2), 1.6]], ext = rectPts(-5, 4, -2.5, 4.5);
    const P = frame(0, ext.concat(poles.map(([q, h]) => add(q, pt(0, 0, h + 1.2)))));
    let g = plate(P, ...[-5, 4, -2.5, 4.5]);
    for (const [q, h] of poles) { const top = add(q, pt(0, 0, h)), t = groundPoint(top, s); g += shadow(P, q, t) + rod(P, q, top) + ray(P, top, t); }
    panels.push([g, 'Vertical edge on the ground', ['The shadow runs along the bearing,', 'AZI + 180°. All vertical edges cast', 'parallel shadows, L = H / tan ALT.']]);
  }
  // 2: a vertical edge meets a wall
  {
    const wall = box(-2.6, 3.6, 2.6, 2.9, 0, 3.2), q = pt(.6, 1), h = 4.2, dir = pt(-s.x / s.z, -s.y / s.z), tw = (2.6 - q.y) / dir.y;
    const foot = add(q, mul(dir, tw)), top = add(foot, pt(0, 0, h - tw));
    const P = frame(1, [...rectPts(-3.5, 4.5, -2, 4.5), add(q, pt(0, 0, h + 1.2)), pt(-2.6, 2.9, 3.2)]);
    const sc = scene(p, P, [wall], s, P.facing, P.nearness);
    let g = plate(P, -3.5, 4.5, -2, 4.5) + sc.back + sc.front + shadow(P, q, foot) + shadow(P, foot, top) + rod(P, q, add(q, pt(0, 0, h))) + ray(P, add(q, pt(0, 0, h)), top);
    panels.push([g, 'Vertical edge meets a wall', ['At the wall the shadow turns and', 'climbs it vertically: it stays in the', 'vertical plane of the rays.']]);
  }
  // 3: an edge parallel to the ground
  {
    const a0 = pt(-2, 0), b0 = pt(2, 0), a = pt(-2, 0, 2.6), b = pt(2, 0, 2.6), ga = groundPoint(a, s), gb = groundPoint(b, s);
    const P = frame(2, [...rectPts(-4.5, 3.5, -2, 4.5), pt(-2, 0, 3.8)]);
    let g = plate(P, -4.5, 3.5, -2, 4.5) + shadow(P, a0, ga) + shadow(P, b0, gb) + shadow(P, ga, gb) + rod(P, a0, a) + rod(P, b0, b) + rod(P, a, b) + ray(P, a, ga) + ray(P, b, gb);
    panels.push([g, 'Edge parallel to the ground', ['Its shadow on the ground is parallel', 'and equally long: copy the edge,', 'shifted by one ray.']]);
  }
  // 4: edges perpendicular to a wall
  {
    const wall = box(-3, 3, 0, .3, 0, 3.4), rods = [[pt(0, 0, 2.4), pt(0, -1.6, 2.4)], [pt(-1.8, 0, 1.6), pt(-1.8, -1.1, 1.6)]];
    const P = frame(3, [...rectPts(-3.5, 3.5, -2.5, 3), pt(-3, .3, 3.4), pt(3, 0, 3.4)]);
    const sc = scene(p, P, [wall], s, P.facing, P.nearness);
    let g = plate(P, -3.5, 3.5, -2.5, 3) + sc.back + sc.front;
    for (const [a, b] of rods) { const t = onWall(b, 0); g += shadow(P, a, t) + rod(P, a, b) + ray(P, b, t); }
    panels.push([g, 'Edge perpendicular to a wall', ['Its shadow starts where it touches', 'the wall. Edges perpendicular to the', 'wall cast parallel shadows on it.']]);
  }
  const body = panels.map(([g, title, lines], i) => k.group(`rule-${i + 1}`, p.title(24 + i * W, 30, `RULE ${i + 1}`, { fill: c.alt }) + k.text(24 + i * W, 48, title, { size: 13, weight: 650, fill: c.ink }) + g
    + lines.map((t, j) => k.text(24 + i * W, 296 + j * 15, t, { size: 11.5 })).join(''))).join('');
  return svgDocument(k, { width: 4 * W, height: 350, title: 'Four rules for casting shadows by hand', body });
}

/* 3 · The 45° convention */
export function figSketchConvention(standalone = false) {
  const k = kit(standalone, 'skc'), p = pens(k, 9), c = k.c, s = { x: -1 / Math.sqrt(3), y: -1 / Math.sqrt(3), z: 1 / Math.sqrt(3) };
  let body = '';
  // A: the cube and its body diagonal
  {
    const P = fitAxo(206, 24, corners(box(0, 1, 0, 1, 0, 1)).concat([pt(-.2, -.3, 1.25)]), { x: 50, y: 64, w: 230, h: 230 });
    const cube = box(0, 1, 0, 1, 0, 1), fs = boxFaces(cube);
    let g = '';
    const hidden = [[pt(1, 1, 0), pt(0, 1, 0)], [pt(1, 1, 0), pt(1, 0, 0)], [pt(1, 1, 0), pt(1, 1, 1)]];
    for (const fc of fs.filter(P.facing)) g += p.poly(fc.pts.map(P), { w: PEN.edge, over: 3 });
    g += hidden.map(([a, b]) => p.line(P(a), P(b), { w: .8, dash: '3 3', color: c.muted, bow: 0 })).join('');
    g += p.line(P(pt(0, 0, 0)), P(pt(1, 1, 0)), { w: 1.2, color: c.azi, dash: '5 3', bow: 0 }) + p.line(P(pt(0, 0, 1)), P(pt(1, 0, 0)), { w: 1.2, color: c.third, dash: '5 3', bow: 0 });
    g += p.line(P(pt(-.25, -.25, 1.25)), P(pt(1, 1, 0)), { w: 1.8, color: c.alt, arrow: 'alt', bow: 0 }) + p.dot(P(pt(1, 1, 0)), 2.6, c.alt);
    g += k.label(P(pt(-.25, -.25, 1.25)).x - 6, P(pt(-.25, -.25, 1.25)).y - 4, 'sun ray', { size: 11.5, fill: c.alt, weight: 650, anchor: 'end' });
    g += k.label(P(pt(.5, .5, 0)).x + 6, P(pt(.5, .5, 0)).y + 22, 'plan: 45°', { size: 11.5, fill: c.azi, weight: 650 });
    g += k.label(P(pt(.5, 0, .5)).x - 52, P(pt(.5, 0, .5)).y + 26, 'elevation: 45°', { size: 11.5, fill: c.third, weight: 650 });
    body += k.group('cube', p.title(30, 34, 'A · CUBE DIAGONAL') + g
      + k.text(30, 332, 'Rays run along the body diagonal of a cube:', { size: 11.5 }) + k.text(30, 347, 'from upper left front to lower right rear.', { size: 11.5 })
      + k.text(30, 362, 'True altitude = arctan(1/√2) = 35.3°.', { size: 11.5, fill: c.alt, weight: 650 }));
  }
  // B: plan, every point at height H moves H right and H up the sheet
  {
    const sc = 30, o = { x: 400, y: 250 }, Q = q => ({ x: o.x + q.x * sc, y: o.y - q.y * sc }), H = 2;
    const blockA = box(0, 3, 0, 2, 0, H), wall = box(4.2, 4.4, -1.6, 1.4, 0, 1);
    const polys = [blockA, wall].map(b => castOnPlane(b, s, 'z', 0, 1).map(Q));
    let g = p.hatch(polys, { gap: 3.4 }) + p.outline(polys);
    for (const b of [blockA, wall]) { const r = [pt(b.x[0], b.y[0]), pt(b.x[1], b.y[0]), pt(b.x[1], b.y[1]), pt(b.x[0], b.y[1])].map(Q); g += p.fill(r) + p.poly(r, { w: PEN.profile }); }
    const a = Q(pt(3, 2)), t = Q(pt(3 + H, 2 + H));
    g += p.pencil(a, t, { color: c.alt, over: 0 }) + p.dot(t, 2.4, c.alt);
    g += p.line(a, { x: t.x, y: a.y }, { w: .8, color: c.alt, bow: 0 }) + p.line({ x: t.x, y: a.y }, t, { w: .8, color: c.alt, bow: 0 });
    g += k.label((a.x + t.x) / 2, a.y + 15, 'H', { size: 12, fill: c.alt, weight: 700, anchor: 'middle' }) + k.label(t.x + 8, (a.y + t.y) / 2 + 4, 'H', { size: 12, fill: c.alt, weight: 700 });
    g += k.text(Q(pt(1.5, 1)).x, Q(pt(1.5, 1)).y + 4, `+${H}.0`, { size: 11, anchor: 'middle', fill: c.ink }) + k.text(Q(pt(4.3, -1.9)).x, Q(pt(4.3, -1.9)).y + 6, '+1.0', { size: 11, anchor: 'middle', fill: c.ink });
    g += p.line({ x: 340, y: 304 }, { x: 368, y: 276 }, { w: 1.4, color: c.alt, arrow: 'alt', bow: 0 }) + k.text(336, 318, 'sun', { size: 11, fill: c.alt, weight: 650 });
    body += k.group('plan', p.title(330, 34, 'B · PLAN') + g
      + k.text(330, 332, 'A point at height H casts its shadow', { size: 11.5 }) + k.text(330, 347, 'H to the right and H up the sheet.', { size: 11.5 })
      + k.text(330, 362, 'Read H from the spot height: no angle needed.', { size: 11.5 }));
  }
  // C: elevation, every projection d moves its shadow d down and d right
  {
    const sc = 34, o = { x: 690, y: 300 }, E = (u, v) => ({ x: o.x + u * sc, y: o.y - v * sc }), d = 1.0, r = .45;
    const rect = (u0, u1, v0, v1) => [E(u0, v0), E(u1, v0), E(u1, v1), E(u0, v1)];
    const wall = rect(0, 7.6, 0, 6.6), slab = [.7, 3.5, 3.1, 3.3], win = [4.8, 6.8, .9, 2.6], win2 = [4.8, 6.8, 4, 5.6];
    const slabShadow = convexHull([[slab[0], slab[2]], [slab[1], slab[2]], [slab[0], slab[3]], [slab[1], slab[3]]].flatMap(([u, v]) => [{ x: u, y: v }, { x: u + d, y: v - d }])).map(q => E(q.x, q.y));
    const recess = w => { const [u0, u1, v0, v1] = w; return [E(u0, v1), E(u1, v1), E(u1, v1 - r), E(u0 + r, v1 - r), E(u0 + r, v0), E(u0, v0)]; };
    let g = p.fill(wall) + p.hatch([slabShadow, recess(win), recess(win2)], { gap: 3.4 }) + p.outline([slabShadow]);
    g += [win, win2].map(w => p.poly(rect(...w), { w: PEN.edge, over: 2 }) + p.line(E((w[0] + w[1]) / 2, w[2]), E((w[0] + w[1]) / 2, w[3]), { w: PEN.hatch })).join('');
    g += p.fill(rect(...slab)) + p.poly(rect(...slab), { w: PEN.outline, over: 3 }) + p.poly(wall, { w: PEN.outline, over: 3 });
    g += p.line(E(-.8, 0), E(8.4, 0), { w: PEN.profile + .4, over: 0 });
    const A = E(slab[1], slab[2]), B = E(slab[1] + d, slab[2] - d);
    g += p.line(A, { x: B.x, y: A.y }, { w: .8, color: c.alt, bow: 0 }) + p.line({ x: B.x, y: A.y }, B, { w: .8, color: c.alt, bow: 0 }) + p.dot(B, 2.4, c.alt);
    g += k.label((A.x + B.x) / 2, A.y - 5, 'd', { size: 12, fill: c.alt, weight: 700, anchor: 'middle' }) + k.label(B.x + 6, (A.y + B.y) / 2 + 4, 'd', { size: 12, fill: c.alt, weight: 700 });
    g += p.line(E(-.6, 6.9), E(.2, 6.1), { w: 1.4, color: c.alt, arrow: 'alt', bow: 0 }) + k.text(E(-.6, 6.9).x - 4, E(-.6, 6.9).y - 4, 'sun', { size: 11, fill: c.alt, weight: 650 });
    g += k.label(E(2.1, 3.2).x, E(2.1, 3.2).y - 18, 'balcony, projects d', { size: 11, anchor: 'middle', fill: c.ink });
    body += k.group('elevation', p.title(650, 34, 'C · ELEVATION') + g
      + k.text(650, 332, 'Anything projecting d from the wall casts', { size: 11.5 }) + k.text(650, 347, 'its shadow d down and d to the right.', { size: 11.5 })
      + k.text(650, 362, 'Window reveals of depth r: shadow r wide.', { size: 11.5 }));
  }
  return svgDocument(k, { width: 990, height: 380, title: 'The 45° convention: sun along the cube diagonal', body });
}

/* 4 · Site plan at a real date and time */
export function figSketchPlan(standalone = false, day = 80, hour = 10) {
  const k = kit(standalone, 'skp'), p = pens(k, 13), c = k.c, sun = solarPosition(42.4, day, hour), s = { x: sun.east, y: sun.north, z: sun.up };
  const sc = 11.5, o = { x: 250, y: 360 }, Q = q => ({ x: o.x + q.x * sc, y: o.y - q.y * sc }), F = 1 / tand(sun.altitude);
  const A = box(0, 12, 0, 8, 0, 9), B = box(-4, 6, 8, 14, 0, 3), wall = box(17, 17.3, -9, 1, 0, 2), trunk = box(21.8, 22.2, 4.8, 5.2, 0, 3);
  const tree = { c: pt(22, 5, 6), r: 3 }, dir = pt(-s.x / s.z, -s.y / s.z), u = mul(dir, 1 / Math.hypot(dir.x, dir.y)), w = pt(-u.y, u.x);
  const ec = add(tree.c, mul(dir, tree.c.z)), ellipse = Array.from({ length: 48 }, (_, i) => { const t = i / 48 * 2 * Math.PI; return add(add(ec, mul(u, tree.r / sind(sun.altitude) * Math.cos(t))), mul(w, tree.r * Math.sin(t))); });
  const foot = b => [pt(b.x[0], b.y[0]), pt(b.x[1], b.y[0]), pt(b.x[1], b.y[1]), pt(b.x[0], b.y[1])];
  const ground = [A, B, wall, trunk].map(b => castOnPlane(b, s, 'z', 0, 1).map(Q)).concat([ellipse.map(Q)]);
  const roof = clipRect(castOnPlane(A, s, 'z', 3, 1), [B.x[0], B.x[1], B.y[0], B.y[1]]).map(Q);
  let g = p.hatch(ground, { gap: 3.4, holes: [A, B, wall].map(b => foot(b).map(Q)) }) + p.outline(ground, [A, B, wall].map(b => foot(b).map(Q)));
  g += [B, A, wall].map(b => p.fill(foot(b).map(Q))).join('') + p.hatch([roof], { gap: 3.4 }) + p.outline([roof]);
  g += [B, A, wall].map(b => p.poly(foot(b).map(Q), { w: PEN.profile })).join('');
  g += p.tree(Q(tree.c), tree.r * sc) + p.dot(Q(tree.c), 1.6);
  g += [['+9.0', pt(6, 4)], ['+3.0', pt(-1, 12.4)], ['+2.0', pt(15.6, -6)], ['tree +9.0', pt(22, 1.2)]].map(([t, q]) => k.label(Q(q).x, Q(q).y + 4, t, { size: 11, anchor: 'middle', fill: c.ink })).join('');
  // Construction at the south-west corner: bearing, folded altitude triangle, tip.
  const B0 = pt(0, 0), T = add(B0, mul(u, 9 * F)), fold = add(B0, mul(w, 9));
  let con = p.pencil(Q(B0), Q(add(B0, mul(u, 9 * F + 3))), { color: c.azi, w: 1 }) + p.pencil(Q(B0), Q(fold), { color: c.alt, w: 1, over: 2 }) + p.line(Q(fold), Q(T), { w: 1, color: c.alt, bow: 0 });
  con += p.dot(Q(T), 2.6, c.alt) + p.dot(Q(fold), 2, c.alt);
  const aT = screenAngle(Q(T), Q(B0)), aH = screenAngle(Q(T), Q(fold));
  con += p.angle(Q(T), 26, Math.min(aT, aH), Math.max(aT, aH), '', c.alt) + k.label(Q(T).x - 30, Q(T).y + 46, `ALT ${sun.altitude.toFixed(1)}°`, { size: 11.5, fill: c.alt, weight: 650, anchor: 'end' });
  con += k.label(lerp(Q(B0), Q(fold), .5).x + 14, lerp(Q(B0), Q(fold), .5).y + 10, 'H = 9 m, folded flat', { size: 11.5, fill: c.alt, weight: 650 });
  con += k.label(lerp(Q(B0), Q(T), .45).x + 12, lerp(Q(B0), Q(T), .45).y + 2, `L = ${(9 * F).toFixed(1)} m`, { size: 11.5, fill: c.azi, weight: 650 });
  // North arrow and sun direction
  const N = { x: 470, y: 70 };
  con += p.line({ x: N.x, y: N.y + 34 }, N, { w: 1.6, arrow: 'ink', bow: 0 }) + k.text(N.x, N.y - 8, 'N', { size: 14, anchor: 'middle', weight: 700, fill: c.ink });
  const sunAt = { x: 470, y: 420 };
  con += p.line({ x: sunAt.x + u.x * 10, y: sunAt.y - u.y * 10 }, { x: sunAt.x + u.x * 46, y: sunAt.y - u.y * 46 }, { w: 1.4, color: c.alt, arrow: 'alt', bow: 0 }) + k.circle(sunAt, 7, { stroke: c.alt, width: 1.4 });
  con += k.text(sunAt.x - 10, sunAt.y + 26, `AZI ${sun.azimuth.toFixed(1)}°`, { size: 11.5, fill: c.azi, weight: 650 });
  let body = k.group('plan', p.title(30, 34, `SITE PLAN · ITHACA · MAR 21 · ${String(hour).padStart(2, '0')}:00 SOLAR`) + g) + k.group('construction', con);
  // Shadow scale: one pole at drawing scale, parallel rays at ALT.
  {
    const o2 = { x: 900, y: 360 }, s2 = 11.5, heights = [2, 3, 9];
    let sc2 = p.title(560, 34, 'SHADOW SCALE · DRAW ONCE, READ ALL HEIGHTS');
    sc2 += p.line({ x: 560, y: o2.y }, { x: o2.x + 20, y: o2.y }, { w: PEN.outline, over: 0 }) + p.line(o2, { x: o2.x, y: o2.y - 9 * s2 }, { w: 2.6, over: 0 });
    for (let h = 1; h <= 9; h++) sc2 += p.line({ x: o2.x, y: o2.y - h * s2 }, { x: o2.x + 5, y: o2.y - h * s2 }, { w: .7, bow: 0 }) + (h % 3 === 0 || h === 2 ? k.text(o2.x + 10, o2.y - h * s2 + 4, `${h} m`, { size: 11, fill: c.ink }) : '');
    heights.forEach((h, i) => {
      const top = { x: o2.x, y: o2.y - h * s2 }, tip = { x: o2.x - h * F * s2, y: o2.y };
      sc2 += p.line(top, tip, { w: 1, color: c.alt, bow: 0 }) + p.dot(tip, 2.3, c.alt);
      const y = o2.y + 20 + i * 18;
      sc2 += p.line({ x: tip.x, y: o2.y + 4 }, { x: tip.x, y: y + 2 }, { w: .6, color: c.muted, bow: 0 }) + p.line({ x: tip.x, y }, { x: o2.x, y }, { w: .9, color: c.azi, bow: 0 }) + k.label(tip.x - 6, y + 4, `${h} m → ${(h * F).toFixed(1)} m`, { size: 11.5, fill: c.azi, weight: 650, anchor: 'end' });
    });
    sc2 += p.angle({ x: o2.x - 9 * F * s2, y: o2.y }, 30, 0, sun.altitude, `${sun.altitude.toFixed(1)}°`, c.alt, { offset: 16 });
    sc2 += k.text(560, 450, `Each meter of height casts ${F.toFixed(2)} m of shadow (1 / tan ALT).`, { size: 11.5 }) + k.text(560, 466, 'Take lengths off with dividers; lay them along the bearing.', { size: 11.5 });
    body += k.group('shadow-scale', sc2);
  }
  body += k.text(30, 540, 'Shadow of block A (+9 m) falls partly on the roof of block B (+3 m): there the shadow only needs the height difference, 6 m × ' + F.toFixed(2) + '.', { size: 11.5 });
  return svgDocument(k, { width: 1000, height: 560, title: 'Plan shadows at Ithaca, March 21, 10:00 solar time', body });
}

/* 5 · Elevation constructed from plan and section */
export function figSketchElevation(standalone = false, day = 80, hour = 14) {
  const k = kit(standalone, 'ske'), p = pens(k, 21), c = k.c, sun = solarPosition(42.4, day, hour);
  const hsa = sun.azimuth - 180, vsa = Math.atan(tand(sun.altitude) / cosd(hsa)) / RAD, th = tand(hsa), tv = tand(vsa);
  const sc = 34, X0 = 50, G = 520, YP = 150, XS = 590;
  const E = (u, v) => ({ x: X0 + u * sc, y: G - v * sc });            // elevation: u along facade, v up
  const PL = (u, w) => ({ x: X0 + u * sc, y: YP + w * sc });          // plan above: w out of the wall toward the viewer
  const SE = (w, v) => ({ x: XS - w * sc, y: G - v * sc });           // section to the right: w out of the wall to the left
  const cast = (u, v, w) => ({ u: u + w * th, v: v - w * tv });       // shadow on the wall of a point w in front of it
  const rect = (u0, u1, v0, v1) => [E(u0, v0), E(u1, v0), E(u1, v1), E(u0, v1)];
  const Wd = 12, Ht = 7.4;
  const cornice = { u: [0, Wd], v: [7.0, 7.4], w: .8 }, balcony = { u: [1.4, 5.4], v: [3.3, 3.5], w: 1.4 }, fin = { u: [7.0, 7.2], v: [4.0, 6.3], w: .7 };
  const win = [[7.6, 10.6, .9, 2.6], [7.6, 10.6, 4.2, 5.9], [2.0, 4.8, 4.2, 5.9]], door = [2.2, 4.0, 0, 2.4], rev = .3;
  const projShadow = e => convexHull([e.u[0], e.u[1]].flatMap(u => [e.v[0], e.v[1]].flatMap(v => { const q = cast(u, v, e.w); return [{ x: u, y: v }, { x: q.u, y: q.v }]; })));
  const clipWall = poly => clipRect(poly, [0, Wd, 0, Ht]).map(q => E(q.x, q.y));
  const recess = ([u0, u1, v0, v1]) => { const lit = clipRect([{ x: u0, y: v0 }, { x: u1, y: v0 }, { x: u1, y: v1 }, { x: u0, y: v1 }].map(q => ({ x: q.x + rev * th, y: q.y - rev * tv })), [u0, u1, v0, v1]);
    return { all: [E(u0, v0), E(u1, v0), E(u1, v1), E(u0, v1)], lit: lit.map(q => E(q.x, q.y)) }; };
  const shadows = [cornice, balcony, fin].map(projShadow).map(clipWall), openings = [...win, door].map(recess);
  // Elevation
  let el = p.fill(rect(0, Wd, 0, Ht));
  el += p.hatch([...shadows, ...openings.map(o => o.all)], { gap: 3.4, holes: openings.map(o => o.lit) }) + p.outline(shadows) + p.outline(openings.map(o => o.lit));
  el += [...win, door].map(o => p.poly(rect(...o), { w: PEN.edge, over: 2 })).join('') + win.map(([u0, u1, v0, v1]) => p.line(E((u0 + u1) / 2, v0), E((u0 + u1) / 2, v1), { w: PEN.hatch })).join('');
  el += [balcony, fin].map(e => p.fill(rect(e.u[0], e.u[1], e.v[0], e.v[1])) + p.poly(rect(e.u[0], e.u[1], e.v[0], e.v[1]), { w: PEN.outline, over: 3 })).join('');
  el += p.poly(rect(0, Wd, cornice.v[0], cornice.v[1]), { w: PEN.outline, over: 3 }) + p.poly(rect(0, Wd, 0, Ht), { w: PEN.outline, over: 3 });
  el += p.line(E(-1.2, 0), E(Wd + 1.2, 0), { w: PEN.profile + .5, over: 0 });
  // Plan (projecting elements seen from above)
  let pl = p.line(PL(-.6, 0), PL(Wd + .6, 0), { w: PEN.profile }) + p.line(PL(-.6, -.35), PL(Wd + .6, -.35), { w: PEN.edge }) + p.hatch([[PL(0, -.35), PL(Wd, -.35), PL(Wd, 0), PL(0, 0)]], { gap: 2.4, angle: 135 });
  pl += p.poly([PL(0, 0), PL(Wd, 0), PL(Wd, cornice.w), PL(0, cornice.w)], { w: .9, dash: '5 3', over: 0 });
  pl += [balcony, fin].map(e => p.fill([PL(e.u[0], 0), PL(e.u[1], 0), PL(e.u[1], e.w), PL(e.u[0], e.w)]) + p.poly([PL(e.u[0], 0), PL(e.u[1], 0), PL(e.u[1], e.w), PL(e.u[0], e.w)], { w: PEN.outline, over: 2 })).join('');
  // Section (profiles of all projections, seen from the east)
  let se = p.line(SE(-.35, -0), SE(-.35, Ht), { w: PEN.edge }) + p.line(SE(0, 0), SE(0, Ht), { w: PEN.profile }) + p.hatch([[SE(0, 0), SE(-.35, 0), SE(-.35, Ht), SE(0, Ht)]], { gap: 2.4, angle: 135 });
  se += p.line(SE(-.6, 0), SE(2.4, 0), { w: PEN.profile + .5, over: 0 });
  se += [cornice, balcony].map(e => p.fill([SE(0, e.v[0]), SE(e.w, e.v[0]), SE(e.w, e.v[1]), SE(0, e.v[1])]) + p.poly([SE(0, e.v[0]), SE(e.w, e.v[0]), SE(e.w, e.v[1]), SE(0, e.v[1])], { w: PEN.outline, over: 2 })).join('');
  se += p.poly([SE(0, fin.v[0]), SE(fin.w, fin.v[0]), SE(fin.w, fin.v[1]), SE(0, fin.v[1])], { w: .9, dash: '4 3', over: 0 });
  // Construction: rays in plan (HSA) and section (VSA), carried into the elevation.
  let con = '';
  const keyPts = [
    { e: balcony, u: balcony.u[1], v: balcony.v[0], w: balcony.w, tag: '1' },
    { e: fin, u: fin.u[1], v: fin.v[0], w: fin.w, tag: '2' },
    { e: cornice, u: 0, v: cornice.v[0], w: cornice.w, tag: '3' },
  ];
  for (const q of keyPts) {
    const hit = cast(q.u, q.v, q.w), from = PL(q.u, q.w), atWall = PL(hit.u, 0);
    con += p.line({ x: from.x - th * 30, y: from.y + 30 }, atWall, { w: 1, color: c.azi, bow: 0 }) + p.dot(atWall, 2, c.azi);
    con += p.pencil(atWall, E(hit.u, hit.v), { over: 0 });
    const sFrom = SE(q.w, q.v), sHit = SE(0, hit.v);
    con += p.line({ x: sFrom.x - 34, y: sFrom.y - 34 * tv }, sHit, { w: 1, color: c.third, bow: 0 }) + p.dot(sHit, 2, c.third);
    con += p.pencil(sHit, E(hit.u, hit.v), { over: 0 });
    con += p.dot(E(hit.u, hit.v), 2.6, c.ink) + k.label(E(hit.u, hit.v).x + 6, E(hit.u, hit.v).y + 14, q.tag, { size: 11.5, fill: c.ink, weight: 700 });
    con += k.label(from.x + 6, from.y + 14, q.tag, { size: 11, fill: c.azi, weight: 700 }) + k.label(sFrom.x - 10, sFrom.y + 14, q.tag, { size: 11, fill: c.third, weight: 700, anchor: 'end' });
  }
  // Angle marks
  { const a = PL(keyPts[0].u, keyPts[0].w);
    con += p.pencil(a, { x: a.x, y: a.y + 40 }, { over: 0, dash: '2 3' }) + p.angle(a, 26, 270 - hsa, 270, '', c.azi) + k.label(a.x - 8, a.y + 50, `HSA ${hsa.toFixed(1)}°`, { size: 11.5, fill: c.azi, weight: 650, anchor: 'end' }); }
  { const a = SE(cornice.w, cornice.v[0]); con += p.pencil(a, { x: a.x - 44, y: a.y }, { over: 0, dash: '2 3' }) + p.angle(a, 26, 180 - vsa, 180, '', c.third) + k.label(a.x - 30, a.y - 34, `VSA ${vsa.toFixed(1)}°`, { size: 11.5, fill: c.third, weight: 650, anchor: 'end' }); }
  const body = k.group('plan', p.title(X0, YP - 34, 'PLAN') + pl) + k.group('section', p.title(XS - 70, G + 34, 'SECTION') + se) + k.group('elevation', p.title(X0, G + 34, 'SOUTH ELEVATION') + el)
    + k.group('construction', con)
    + k.group('notes', p.title(700, YP - 34, `ITHACA · MAR 21 · ${hour}:00 SOLAR`) + k.text(700, YP - 16, `ALT ${sun.altitude.toFixed(1)}° · AZI ${sun.azimuth.toFixed(1)}° · facade faces south`, { size: 11.5 })
      + [[`Plan: draw rays at HSA = AZI − 180° = ${hsa.toFixed(1)}°`, 'to the facade normal. Each gives the sideways', `shift w · tan HSA = ${th.toFixed(2)} w.`],
        [`Section: draw rays at VSA = ${vsa.toFixed(1)}° (Eq. 17).`, `Each gives the drop w · tan VSA = ${tv.toFixed(2)} w.`],
        ['Project both into the elevation. Where the', 'lines cross is the shadow of that point.'],
        ['Join the points with lines parallel to the', 'casting edges, then hatch.']]
        .map((lines, i) => k.text(700, YP + 30 + i * 62, String(i + 1), { size: 15, weight: 700, fill: c.alt }) + lines.map((t, j) => k.text(720, YP + 30 + i * 62 + j * 15, t, { size: 11.5, fill: c.ink })).join('')).join('')
      + k.text(700, YP + 290, `Point 1, balcony edge, w = 1.4 m:`, { size: 11.5 }) + k.text(700, YP + 305, `${(1.4 * th).toFixed(2)} m across, ${(1.4 * tv).toFixed(2)} m down.`, { size: 11.5 })
      + k.text(700, YP + 320, 'Window reveals (w = 0.3 m) follow the same rule.', { size: 11.5 }));
  return svgDocument(k, { width: 1000, height: 580, title: 'Elevation shadows constructed from plan and section', body });
}

/* 6 · Axonometric */
export function figSketchAxo(standalone = false, day = 80, hour = 15) {
  const k = kit(standalone, 'ska'), p = pens(k, 17), c = k.c, sun = solarPosition(42.4, day, hour), s = { x: sun.east, y: sun.north, z: sun.up };
  const tower = box(0, 6, 0, 6, 0, 12), low = box(8, 20, 8, 12, 0, 4.5), pole = [pt(-4, -7), pt(-4, -7, 4)];
  const { P, back, front } = axoScene(p, [tower, low], s, { psi: 150, eps: 30, frame: { x: 30, y: 60, w: 610, h: 380 }, extra: [...pole, groundPoint(pole[1], s), add(pole[1], mul(s, 2.5)), pt(22, 18)] });
  // 1: the pole's shadow lands on the ground. 2: the tower's south-east edge reaches the wall first and climbs it.
  const g1 = groundPoint(pole[1], s), c2 = pt(6, 0, 12), dir = pt(-s.x / s.z, -s.y / s.z), t2 = (low.y[0] - c2.y) / dir.y;
  const foot2 = add(pt(c2.x, c2.y), mul(dir, t2)), hit2 = add(foot2, pt(0, 0, 12 - t2));
  let con = strip(p, P, pole[0], g1) + member(p, P, ...pole);
  con += p.pencil(P(pole[0]), P(g1), { color: c.azi, w: 1 }) + p.line(P(add(pole[1], mul(s, 2.5))), P(g1), { w: 1, color: c.alt, arrow: 'alt', bow: 0 }) + p.dot(P(g1), 2.6, c.alt);
  con += p.pencil(P(pt(6, 0)), P(foot2), { color: c.azi, w: 1 }) + p.pencil(P(foot2), P(hit2), { color: c.azi, w: 1, over: 0 }) + p.line(P(add(c2, mul(s, 2.5))), P(hit2), { w: 1, color: c.alt, arrow: 'alt', bow: 0 }) + p.dot(P(hit2), 2.6, c.alt);
  con += [[g1, '1'], [hit2, '2']].map(([q, t]) => k.label(P(q).x + 8, P(q).y + 16, t, { size: 13, weight: 700, fill: c.alt })).join('');
  const body = p.title(30, 34, `AXONOMETRIC · ITHACA · MAR 21 · ${hour}:00 SOLAR`) + k.group('shadows-ground', back) + k.group('buildings', front) + k.group('construction', con)
    + k.group('notes', [
      ['Find the shadow of one point in plan', `(Eq. 22; the 4 m pole casts ${(4 / tand(sun.altitude)).toFixed(1)} m) and draw`, 'that ray. All other rays are parallel to it.'],
      ['Through each base point draw a bearing line;', 'through its top, a ray. Where they cross is', 'the shadow point (1).'],
      ['If the bearing line meets a wall first, turn', 'up the wall until it meets the ray (2).'],
      ['Connect the points. Edges parallel to the', 'ground or to the wall cast parallel shadows:', 'most of the outline is copied, not constructed.'],
    ].map((lines, i) => k.text(668, 96 + i * 72, String(i + 1), { size: 15, weight: 700, fill: c.alt }) + lines.map((t, j) => k.text(690, 96 + i * 72 + j * 15, t, { size: 11.5, fill: c.ink })).join('')).join('')
      + k.text(668, 390, `ALT ${sun.altitude.toFixed(1)}° · AZI ${sun.azimuth.toFixed(1)}° · tower 12 m · block 4.5 m`, { size: 11.5 }));
  return svgDocument(k, { width: 1000, height: 450, title: 'Axonometric shadow construction', body });
}

/* 7 · Perspective: sun parallel to the picture plane, behind and in front of the viewer */
export function figSketchPerspective(standalone = false) {
  const k = kit(standalone, 'skx'), p = pens(k, 23), c = k.c, PH = 350;
  const cube = box(0, 5, 0, 5, 0, 4.5), eye = pt(-10, -10, 3.2), yaw = 45, fl = 300, cx = 330;
  const cases = [
    { title: 'A · SUN PARALLEL TO THE PICTURE PLANE', s: sunVector(36, yaw - 90), horizon: 160, text: ['Rays keep their true angle (ALT) and stay', 'parallel. Shadows of vertical edges are', 'horizontal. The quickest construction.'] },
    { title: 'B · SUN BEHIND THE VIEWER', s: sunVector(20, yaw + 220), horizon: 110, text: ['Lit faces toward you; shadows fall away and', 'are partly hidden. Rays converge to VPs below', 'the horizon; shadows of verticals converge to', 'VPsh on it, vertically above VPs.'] },
    { title: 'C · SUN IN FRONT OF THE VIEWER (BACKLIGHT)', s: sunVector(28, yaw + 20), horizon: 200, eyeHeight: 1.8, text: ['Faces toward you are in shade; shadows', 'come toward you. VPs is the sun itself,', 'above the horizon; VPsh is directly below it.'] },
  ];
  let body = '';
  cases.forEach((cs, i) => {
    const y0 = i * PH, P = camera({ ...eye, z: cs.eyeHeight ?? eye.z }, yaw, fl, cx, y0 + cs.horizon), s = cs.s;
    const { back, front } = scene(p, P, [cube], s, P.facing, P.nearness);
    const vpx = P.vp(pt(1, 0)), vpy = P.vp(pt(0, 1));
    let g = p.pencil({ x: 30, y: P.horizon }, { x: 660, y: P.horizon }, { over: 0, w: .9 }) + k.text(34, P.horizon - 6, 'HL · eye height', { size: 10.5, fill: c.muted });
    for (const [vp, name] of [[vpx, 'VPR'], [vpy, 'VPL']]) {
      g += p.dot(vp, 2.2, c.muted) + k.text(vp.x, P.horizon + 16, name, { size: 10.5, anchor: 'middle', fill: c.muted });
      for (const q of [pt(0, 0), pt(0, 0, 4.5)]) g += p.pencil(vp, P(q), { over: 0, w: .5 });
    }
    // Rays and shadow lines for the three visible vertical edges.
    const edges = [pt(0, 0), pt(5, 0), pt(0, 5)], post = i === 1 ? [pt(7.5, -3), pt(7.5, -3, 3)] : null;
    const shadowVP = P.vp(pt(-s.x, -s.y)), rayVP = P.vp(pt(-s.x, -s.y, -s.z));
    let con = '';
    for (const q of edges) {
      const top = add(q, pt(0, 0, 4.5)), tip = groundPoint(top, s);
      if (i === 0) {
        const dir = { x: P(add(top, mul(s, -1))).x - P(top).x, y: P(add(top, mul(s, -1))).y - P(top).y }, L = Math.hypot(dir.x, dir.y);
        con += p.pencil({ x: P(top).x - dir.x / L * 50, y: P(top).y - dir.y / L * 50 }, P(tip), { color: c.alt, w: .9, over: 0 }) + p.pencil(P(q), P(tip), { color: c.azi, w: .9, over: 6 });
      } else {
        con += p.pencil(rayVP, P(tip), { color: c.alt, w: .8, over: 6 }) + p.pencil(shadowVP, P(tip), { color: c.azi, w: .8, over: 6 });
      }
      con += p.dot(P(tip), 2.2, c.alt);
    }
    if (post) {
      const tip = groundPoint(post[1], s);
      con += p.pencil(rayVP, P(tip), { color: c.alt, w: .8, over: 6 }) + p.pencil(shadowVP, P(tip), { color: c.azi, w: .8, over: 6 }) + strip(p, P, post[0], tip) + member(p, P, ...post) + p.dot(P(tip), 2.2, c.alt);
    }
    if (i > 0) {
      con += p.pencil(shadowVP, rayVP, { over: 0, dash: '3 3', w: .7 }) + p.dot(shadowVP, 3, c.azi) + p.dot(rayVP, 3, c.alt);
      con += k.label(shadowVP.x + 8, shadowVP.y - 7, 'VPsh', { size: 11.5, fill: c.azi, weight: 700 }) + k.label(rayVP.x + 8, rayVP.y + (i === 1 ? 14 : -6), i === 2 ? 'VPs = sun' : 'VPs', { size: 11.5, fill: c.alt, weight: 700 });
      if (i === 2) con += k.circle(rayVP, 9, { stroke: c.alt, width: 1.2 });
    } else {
      const top = pt(5, 0, 4.5), T = P(groundPoint(top, s)), a0 = screenAngle(T, P(pt(5, 0))), a1 = screenAngle(T, P(top)), lo = Math.min(a0, a1), hi = Math.max(a0, a1);
      con += hi - lo > 180 ? p.angle(T, 30, hi, lo + 360, 'ALT 36°', c.alt, { offset: 22 }) : p.angle(T, 30, lo, hi, 'ALT 36°', c.alt, { offset: 22 });
    }
    body += k.group(`case-${'abc'[i]}`, p.title(30, y0 + 28, cs.title) + g + k.group(`shadow-${'abc'[i]}`, back) + front + con
      + cs.text.map((t, j) => k.text(720, y0 + 110 + j * 17, t, { size: 11.5, fill: c.ink })).join('')
      + (i < 2 ? p.line({ x: 30, y: y0 + PH - 12 }, { x: 970, y: y0 + PH - 12 }, { w: .5, color: c.grid, bow: 0 }) : ''));
  });
  return svgDocument(k, { width: 1000, height: 3 * PH, title: 'Shadows in two-point perspective for three sun directions', body });
}

/* 8 · Fine-liner technique */
export function figSketchTechnique(standalone = false) {
  const k = kit(standalone, 'skt'), p = pens(k, 31), c = k.c;
  let body = p.title(30, 34, 'PEN WEIGHTS');
  [[PEN.pencil, 'pencil / 0.05', 'construction: rays, bearings, VPs', c.axis], [PEN.hatch, '0.1', 'hatching, shadow outlines, glazing'], [PEN.edge, '0.3', 'edges between visible faces'],
    [PEN.outline, '0.5', 'outlines against the background'], [PEN.profile, '0.7', 'ground line, cut walls, plan outlines']].forEach(([w, name, use, color], i) => {
    const y = 64 + i * 26;
    body += p.line({ x: 30, y }, { x: 170, y }, { w, color, over: 0 }) + k.text(186, y + 4, name, { size: 11.5, fill: c.ink, weight: 650 }) + k.text(270, y + 4, use, { size: 11.5 });
  });
  body += p.title(560, 34, 'VALUES WITH ONE PEN');
  [['light', 'light', 'paper'], ['shade', 'shade', 'open hatch'], ['shadow', 'shadow', 'dense hatch'], ['cross', 'shadow', 'cross-hatch'], ['stipple', 'shadow', 'stipple'], ['dark', 'void, glass', 'double hatch']].forEach(([kind, a, b], i) => {
    const x = 560 + i * 72;
    body += swatch(p, x, 52, 54, 64, kind) + k.text(x, 134, a, { size: 11, fill: c.ink, weight: 650 }) + k.text(x, 148, b, { size: 11 });
  });
  // Do / don't on the same small box
  const s = sunVector(36, 128), b = [box(0, 6, 0, 4, 0, 4.5), box(.8, 4.4, -1.7, 0, 3, 3.2)];
  const good = axoScene(p, b, s, { psi: 212, eps: 27, frame: { x: 40, y: 230, w: 380, h: 210 } });
  body += p.title(30, 210, 'DO') + good.back + good.front;
  const bad = axoScene(p, b, s, { psi: 212, eps: 27, frame: { x: 530, y: 230, w: 380, h: 210 }, groundHatch: false, shadeGap: 2.2, angle: 0 });
  const heavy = bad.groundPolys;
  body += p.title(520, 210, 'AVOID') + p.hatch(heavy, { gap: 7, angle: 100 }) + p.outline(heavy, [], { w: PEN.profile + .6 }) + bad.front;
  body += [['One hatch direction across the whole drawing.', 'Shadow darker than shade; light faces stay white.', 'Crisp shadow edges come from where strokes stop.'],
    ['Heavy outlines around shadows read as objects.', 'Mixed hatch directions and a shade darker than', 'the shadow flatten the form.']]
    .map((lines, i) => lines.map((t, j) => k.text(30 + i * 490, 470 + j * 16, t, { size: 11.5 })).join('')).join('');
  return svgDocument(k, { width: 1000, height: 530, title: 'Fine-liner technique for shade and shadow', body });
}

/** Figures for Section 13, in reading order: [file name, caption, drawing]. */
export const SKETCH_FIGURES = [
  ['sketch-vocabulary', 'Light, shade and shadow', figSketchVocabulary],
  ['sketch-rules', 'Four rules for casting shadows', figSketchRules],
  ['sketch-convention', 'The 45° convention', figSketchConvention],
  ['sketch-plan', 'Plan shadows at a real date and time, with a shadow scale', figSketchPlan],
  ['sketch-elevation', 'Elevation shadows from plan and section', figSketchElevation],
  ['sketch-axo', 'Axonometric shadow construction', figSketchAxo],
  ['sketch-perspective', 'Shadows in perspective', figSketchPerspective],
  ['sketch-technique', 'Fine-liner technique', figSketchTechnique],
];
